SET SERVEROUTPUT ON

CREATE TABLE employees (
  emp_id    NUMBER PRIMARY KEY,
  emp_name  VARCHAR2(50) NOT NULL,
  dept      VARCHAR2(20) NOT NULL,
  salary    NUMBER(10,2)
);

INSERT INTO employees VALUES (101, 'Asha Rao',    'IT',    65000);
INSERT INTO employees VALUES (102, 'Vikram Shah', 'IT',    72000);
INSERT INTO employees VALUES (103, 'Neha Gupta',  'HR',    48000);
INSERT INTO employees VALUES (104, 'Rahul Verma', 'SALES', 55000);
INSERT INTO employees VALUES (105, 'Priya Nair',  'SALES', 51000);
COMMIT;

BEGIN
  EXECUTE IMMEDIATE
    'CREATE TABLE employees_bkp AS SELECT * FROM employees';
  DBMS_OUTPUT.PUT_LINE('Backup table created');
END;
/

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE employees_bkp PURGE';
  DBMS_OUTPUT.PUT_LINE('Dropped');
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE = -942 THEN
      DBMS_OUTPUT.PUT_LINE('Table did not exist, nothing to drop');
    ELSE
      RAISE;
    END IF;
END;
/

DECLARE
  v_name   employees.emp_name%TYPE;
  v_salary employees.salary%TYPE;
  v_id     NUMBER := 102;
BEGIN
  EXECUTE IMMEDIATE
    'SELECT emp_name, salary FROM employees WHERE emp_id = :id'
    INTO v_name, v_salary
    USING v_id;

  DBMS_OUTPUT.PUT_LINE(v_name || ' earns ' || v_salary);
END;
/

DECLARE
  v_name employees.emp_name%TYPE;
BEGIN
  EXECUTE IMMEDIATE
    'SELECT emp_name FROM employees WHERE emp_id = :id'
    INTO v_name
    USING 999;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No employee with that id');
END;
/

DECLARE
  v_dept VARCHAR2(20) := 'SALES';
  v_pct  NUMBER       := 10;
BEGIN
  EXECUTE IMMEDIATE
    'UPDATE employees
        SET salary = salary * (1 + :pct / 100)
      WHERE dept = :dept'
    USING v_pct, v_dept;

  DBMS_OUTPUT.PUT_LINE(SQL%ROWCOUNT || ' rows updated');
END;
/

DECLARE
  v_new_salary employees.salary%TYPE;
BEGIN
  EXECUTE IMMEDIATE
    'UPDATE employees
        SET salary = salary + :amt
      WHERE emp_id = :id
     RETURNING salary INTO :new_sal'
    USING 5000, 103
    RETURNING INTO v_new_salary;

  DBMS_OUTPUT.PUT_LINE('New salary: ' || v_new_salary);
END;
/

DECLARE
  TYPE t_names IS TABLE OF employees.emp_name%TYPE;
  v_names t_names;
BEGIN
  EXECUTE IMMEDIATE
    'SELECT emp_name FROM employees
      WHERE dept = :d
      ORDER BY emp_name'
    BULK COLLECT INTO v_names
    USING 'IT';

  FOR i IN 1 .. v_names.COUNT LOOP
    DBMS_OUTPUT.PUT_LINE(i || '. ' || v_names(i));
  END LOOP;
END;
/

CREATE OR REPLACE PROCEDURE show_max (p_column IN VARCHAR2) AS
  v_col  user_tab_cols.column_name%TYPE;
  v_max  VARCHAR2(100);
BEGIN
  -- Step 1: the column must really exist on EMPLOYEES
  SELECT column_name
    INTO v_col
    FROM user_tab_cols
   WHERE table_name  = 'EMPLOYEES'
     AND column_name = UPPER(p_column);

  -- Step 2: quote the validated name and build the SQL
  EXECUTE IMMEDIATE
    'SELECT TO_CHAR(MAX(' || DBMS_ASSERT.ENQUOTE_NAME(v_col)
    || ')) FROM employees'
    INTO v_max;

  DBMS_OUTPUT.PUT_LINE('MAX(' || v_col || ') = ' || v_max);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20001, 'Unknown column: ' || p_column);
END;
/

EXEC show_max('salary')
EXEC show_max('emp_id) || (SELECT 1 FROM dual')

DECLARE
  v_total NUMBER := 10;
BEGIN
  EXECUTE IMMEDIATE 'BEGIN :n := :n * 2; END;'
    USING IN OUT v_total;

  DBMS_OUTPUT.PUT_LINE('v_total = ' || v_total);
END;
/

